{-| @Backend.Runtime.Host.Net — stream endpoints behind their tokens, as `Pudu.Eval.Socket` answers them, each refusal worded as the interpreter's runtime words it. -}
module Pudu.Backend.Runtime.Host.Net (hostNetParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
hostNetParts :: [(Text, [Text], [Text])]
hostNetParts =
  [ ("host_sockets", ["host_optional", "host_done", "host_fail", "host_fail_io", "host_grow", "host_gate", "host_path", "kernel_signed", "kernel_int"],
      [ "#include <arpa/inet.h>"
      , "#include <fcntl.h>"
      , "#include <limits.h>"
      , "#include <netdb.h>"
      , "#include <netinet/in.h>"
      , "#include <netinet/tcp.h>"
      , "#include <poll.h>"
      , "#include <sys/socket.h>"
      , "#if defined(__APPLE__) && !defined(SO_NOSIGPIPE)"
      , "#define SO_NOSIGPIPE 0x1022"
      , "#endif"
      , "#if defined(MSG_NOSIGNAL)"
      , "#define PUDU_HOST_SEND_FLAGS MSG_NOSIGNAL"
      , "#else"
      , "#define PUDU_HOST_SEND_FLAGS 0"
      , "#endif"
      , "/* Endpoints behind their tokens, numbered from one in their own run. A slot"
      , "   holds its descriptor plus one, so an empty slot is zero. */"
      , "PUDU_OPTIONAL static int *pudu_host_socket_table = NULL;"
      , "PUDU_OPTIONAL static size_t pudu_host_socket_room = 0, pudu_host_socket_held = 0;"
      , "PUDU_OPTIONAL static int64_t pudu_host_socket_next = 1;"
      , "PUDU_OPTIONAL static inline int pudu_host_socket_find(pudu_int token) {"
      , "  int64_t wanted = pudu_kernel_signed(token.bits);"
      , "  if (wanted < 1 || (uint64_t)wanted >= pudu_host_socket_room) return -1;"
      , "  return pudu_host_socket_table[wanted] - 1;"
      , "}"
      , "/* Forgets the token and answers its descriptor; the table goes with its last endpoint. */"
      , "PUDU_OPTIONAL static inline int pudu_host_socket_take(pudu_int token) {"
      , "  int found = pudu_host_socket_find(token);"
      , "  if (found < 0) return -1;"
      , "  pudu_host_socket_table[pudu_kernel_signed(token.bits)] = 0;"
      , "  pudu_host_socket_held -= 1;"
      , "  if (pudu_host_socket_held == 0) { free(pudu_host_socket_table); pudu_host_socket_table = NULL; pudu_host_socket_room = 0; }"
      , "  return found;"
      , "}"
      , "PUDU_OPTIONAL static inline pudu_int pudu_host_socket_keep(int descriptor) {"
      , "  int64_t token = pudu_host_socket_next++;"
      , "  if ((size_t)token >= pudu_host_socket_room) {"
      , "    size_t room = pudu_host_socket_room < 8 ? 8 : pudu_host_socket_room * 2;"
      , "    int *table;"
      , "    while (room <= (size_t)token) room *= 2;"
      , "    table = pudu_host_grow(pudu_host_socket_table, room * sizeof *table);"
      , "    memset(table + pudu_host_socket_room, 0, (room - pudu_host_socket_room) * sizeof *table);"
      , "    pudu_host_socket_table = table;"
      , "    pudu_host_socket_room = room;"
      , "  }"
      , "  pudu_host_socket_table[token] = descriptor + 1;"
      , "  pudu_host_socket_held += 1;"
      , "  return pudu_kernel_int(token);"
      , "}"
      , "/* A descriptor never blocks, is not handed to started programs, and answers"
      , "   a failure rather than a signal when its peer has gone. */"
      , "PUDU_OPTIONAL static inline void pudu_host_socket_prepare(int descriptor) {"
      , "  int flags = fcntl(descriptor, F_GETFL, 0), one = 1;"
      , "  if (flags >= 0) (void)fcntl(descriptor, F_SETFL, flags | O_NONBLOCK);"
      , "  (void)fcntl(descriptor, F_SETFD, FD_CLOEXEC);"
      , "#if defined(SO_NOSIGPIPE)"
      , "  (void)setsockopt(descriptor, SOL_SOCKET, SO_NOSIGPIPE, &one, sizeof one);"
      , "#else"
      , "  (void)one;"
      , "#endif"
      , "}"
      , "PUDU_OPTIONAL static inline int64_t pudu_host_socket_clock(void) {"
      , "  struct timespec now;"
      , "  (void)clock_gettime(CLOCK_MONOTONIC, &now);"
      , "  return (int64_t)now.tv_sec * 1000 + (int64_t)(now.tv_nsec / 1000000L);"
      , "}"
      , "/* Waits for the descriptor: 1 when it is ready, 0 when the budget of"
      , "   milliseconds counted from the start is spent. A negative budget never ends. */"
      , "PUDU_OPTIONAL static inline int pudu_host_socket_ready(int descriptor, short events, int64_t budget, int64_t started) {"
      , "  for (;;) {"
      , "    struct pollfd watched;"
      , "    int wait = -1, got;"
      , "    watched.fd = descriptor;"
      , "    watched.events = events;"
      , "    watched.revents = 0;"
      , "    if (budget >= 0) {"
      , "      int64_t left = budget - (pudu_host_socket_clock() - started);"
      , "      if (left <= 0) return 0;"
      , "      wait = left > 60000 ? 60000 : (int)left;"
      , "    }"
      , "    got = poll(&watched, 1, wait);"
      , "    if (got > 0 || (got < 0 && errno != EINTR)) return 1;"
      , "  }"
      , "}"
      , "PUDU_OPTIONAL static inline void pudu_host_socket_timed_out(pudu_int token) {"
      , "  int taken = pudu_host_socket_take(token);"
      , "  if (taken >= 0) (void)close(taken);"
      , "  pudu_host_fail(\"operation timed out\");"
      , "}"
      ])
  , ("host_resolve", ["host_sockets", "text_allocate", "memory_failure"],
      [ "/* The first stream address a host and a port name, or nothing after the"
      , "   resolver's refusal has been worded. */"
      , "PUDU_OPTIONAL static inline struct addrinfo *pudu_host_resolve(pudu_text host, pudu_int port, int passive) {"
      , "  struct addrinfo hints, *found = NULL;"
      , "  char service[32];"
      , "  char *name = pudu_host_path(host);"
      , "  int code;"
      , "  memset(&hints, 0, sizeof hints);"
      , "  hints.ai_socktype = SOCK_STREAM;"
      , "  if (passive) hints.ai_flags = AI_PASSIVE;"
      , "  (void)snprintf(service, sizeof service, \"%lld\", (long long)pudu_kernel_signed(port.bits));"
      , "  pudu_host_leave();"
      , "  code = getaddrinfo(passive && host.length == 0 ? NULL : name, service, &hints, &found);"
      , "  pudu_host_enter();"
      , "  if (code != 0 || found == NULL) {"
      , "    static const char opening[] = \"Network.Socket.getAddrInfo (called with preferred socket type/protocol: AddrInfo {addrFlags = [\";"
      , "    static const char middle[] = \"], addrFamily = AF_UNSPEC, addrSocketType = Stream, addrProtocol = 0, addrAddress = 0.0.0.0:0, addrCanonName = Nothing}, host name: \";"
      , "    const char *reason = code != 0 ? gai_strerror(code) : \"\";"
      , "    size_t room = sizeof opening + sizeof middle + host.length * 2 + strlen(service) + strlen(reason) + 96;"
      , "    char *words = malloc(room), *cursor = words;"
      , "    unsigned char *bytes;"
      , "    if (words == NULL) pudu_memory_failure();"
      , "    if (code == 0) {"
      , "      cursor += snprintf(cursor, room, \"no address for %s:%s\", name, service);"
      , "    } else {"
      , "      cursor += snprintf(cursor, room, \"%s%s%s\", opening, passive ? \"AI_PASSIVE\" : \"\", middle);"
      , "      if (passive && host.length == 0) { memcpy(cursor, \"Nothing\", 7); cursor += 7; }"
      , "      else {"
      , "        *cursor++ = '\"';"
      , "        for (size_t index = 0; index < host.length; ++index) {"
      , "          if (host.bytes[index] == '\"' || host.bytes[index] == '\\\\') *cursor++ = '\\\\';"
      , "          *cursor++ = (char)host.bytes[index];"
      , "        }"
      , "        *cursor++ = '\"';"
      , "      }"
      , "      cursor += snprintf(cursor, room - (size_t)(cursor - words), \", service name: \\\"%s\\\"): does not exist (%s)\", service, reason);"
      , "    }"
      , "    pudu_text_release(pudu_host_said);"
      , "    pudu_host_said = pudu_text_allocate((size_t)(cursor - words), &bytes);"
      , "    memcpy(bytes, words, (size_t)(cursor - words));"
      , "    pudu_host_status = 1;"
      , "    free(words);"
      , "    if (found != NULL) freeaddrinfo(found);"
      , "    found = NULL;"
      , "  }"
      , "  free(name);"
      , "  return found;"
      , "}"
      ])
  , ("host_tcp_listen", ["host_resolve"],
      [ "/* An endpoint that waits for connections, on an address it may take again"
      , "   at once after closing. */"
      , "static pudu_int pudu_host_tcp_listen(pudu_text host, pudu_int port, pudu_int backlog) {"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "  struct addrinfo *found = pudu_host_resolve(host, port, 1);"
      , "  const char *failed = NULL;"
      , "  int descriptor, code = 0, one = 1;"
      , "  int64_t waiting = pudu_kernel_signed(backlog.bits);"
      , "  if (found == NULL) return pudu_kernel_int(0);"
      , "  descriptor = socket(found->ai_family, found->ai_socktype, found->ai_protocol);"
      , "  if (descriptor < 0) { code = errno; failed = \"Network.Socket.socket\"; }"
      , "  else {"
      , "    pudu_host_socket_prepare(descriptor);"
      , "    if (setsockopt(descriptor, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one) != 0) { code = errno; failed = \"Network.Socket.setSockOpt\"; }"
      , "    else if (bind(descriptor, found->ai_addr, found->ai_addrlen) != 0) { code = errno; failed = \"Network.Socket.bind\"; }"
      , "    else if (listen(descriptor, waiting < 0 ? 0 : waiting > INT_MAX ? INT_MAX : (int)waiting) != 0) { code = errno; failed = \"Network.Socket.listen\"; }"
      , "  }"
      , "  freeaddrinfo(found);"
      , "  if (failed != NULL) {"
      , "    if (descriptor >= 0) (void)close(descriptor);"
      , "    pudu_host_fail_io(none, failed, code);"
      , "    return pudu_kernel_int(0);"
      , "  }"
      , "  pudu_host_done(0);"
      , "  return pudu_host_socket_keep(descriptor);"
      , "}"
      ])
  , ("host_tcp_accept", ["host_sockets"],
      [ "/* The next connection to a waiting endpoint, under a token of its own. */"
      , "static pudu_int pudu_host_tcp_accept(pudu_int token) {"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "  int listener = pudu_host_socket_find(token), descriptor, code = 0, one = 1;"
      , "  if (listener < 0) { pudu_host_fail(\"the endpoint is closed\"); return pudu_kernel_int(0); }"
      , "  pudu_host_leave();"
      , "  for (;;) {"
      , "    descriptor = accept(listener, NULL, NULL);"
      , "    if (descriptor >= 0) break;"
      , "    code = errno;"
      , "    if (code == EINTR) continue;"
      , "    if (code == EAGAIN || code == EWOULDBLOCK) { (void)pudu_host_socket_ready(listener, POLLIN, -1, 0); continue; }"
      , "    break;"
      , "  }"
      , "  pudu_host_enter();"
      , "  if (descriptor < 0) { pudu_host_fail_io(none, \"Network.Socket.accept\", code); return pudu_kernel_int(0); }"
      , "  pudu_host_socket_prepare(descriptor);"
      , "  (void)setsockopt(descriptor, IPPROTO_TCP, TCP_NODELAY, &one, sizeof one);"
      , "  pudu_host_done(0);"
      , "  return pudu_host_socket_keep(descriptor);"
      , "}"
      ])
  , ("host_socket_dialing", ["host_resolve"],
      [ "/* A connected descriptor to somewhere else within a budget of"
      , "   milliseconds, or -1 after the refusal has been worded. */"
      , "PUDU_OPTIONAL static inline int pudu_host_socket_dialing(pudu_text host, pudu_int port, int64_t budget) {"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "  int64_t started = pudu_host_socket_clock();"
      , "  struct addrinfo *found;"
      , "  int descriptor, code = 0, one = 1;"
      , "  char where[64];"
      , "  if (budget == 0) { pudu_host_fail(\"operation timed out\"); return -1; }"
      , "  found = pudu_host_resolve(host, port, 0);"
      , "  if (found == NULL) return -1;"
      , "  descriptor = socket(found->ai_family, found->ai_socktype, found->ai_protocol);"
      , "  if (descriptor < 0) {"
      , "    code = errno;"
      , "    freeaddrinfo(found);"
      , "    pudu_host_fail_io(none, \"Network.Socket.socket\", code);"
      , "    return -1;"
      , "  }"
      , "  pudu_host_socket_prepare(descriptor);"
      , "  (void)setsockopt(descriptor, IPPROTO_TCP, TCP_NODELAY, &one, sizeof one);"
      , "  pudu_host_leave();"
      , "  if (connect(descriptor, found->ai_addr, found->ai_addrlen) != 0) {"
      , "    code = errno;"
      , "    if (code == EINTR || code == EINPROGRESS) {"
      , "      if (!pudu_host_socket_ready(descriptor, POLLOUT, budget, started)) code = -1;"
      , "      else {"
      , "        socklen_t size = sizeof code;"
      , "        code = 0;"
      , "        if (getsockopt(descriptor, SOL_SOCKET, SO_ERROR, &code, &size) != 0) code = errno;"
      , "      }"
      , "    }"
      , "  }"
      , "  pudu_host_enter();"
      , "  freeaddrinfo(found);"
      , "  if (code != 0) {"
      , "    (void)snprintf(where, sizeof where, \"Network.Socket.connect: <socket: %d>\", descriptor);"
      , "    (void)close(descriptor);"
      , "    if (code < 0) pudu_host_fail(\"operation timed out\");"
      , "    else pudu_host_fail_io(none, where, code);"
      , "    return -1;"
      , "  }"
      , "  pudu_host_done(0);"
      , "  return descriptor;"
      , "}"
      ])
  , ("host_socket_connecting", ["host_socket_dialing"],
      [ "/* A connection to somewhere else, behind a token of its own. */"
      , "PUDU_OPTIONAL static inline pudu_int pudu_host_socket_connecting(pudu_text host, pudu_int port, int64_t budget) {"
      , "  int descriptor = pudu_host_socket_dialing(host, port, budget);"
      , "  return descriptor < 0 ? pudu_kernel_int(0) : pudu_host_socket_keep(descriptor);"
      , "}"
      ])
  , ("host_tcp_connect", ["host_socket_connecting"],
      [ "static pudu_int pudu_host_tcp_connect(pudu_text host, pudu_int port) { return pudu_host_socket_connecting(host, port, -1); }"
      ])
  , ("host_tcp_connect_within", ["host_socket_connecting"],
      [ "static pudu_int pudu_host_tcp_connect_within(pudu_text host, pudu_int port, pudu_int within) {"
      , "  int64_t budget = pudu_kernel_signed(within.bits);"
      , "  return pudu_host_socket_connecting(host, port, budget < 0 ? -1 : budget);"
      , "}"
      ])
  , ("host_socket_sending", ["host_sockets"],
      [ "/* Every byte, however many writes that takes. */"
      , "PUDU_OPTIONAL static inline int pudu_host_socket_sending(pudu_int token, pudu_box *chunk, int64_t budget) {"
      , "  pudu_text bytes = chunk->fields[0].text, none = {(const unsigned char *)\"\", 0, NULL};"
      , "  int descriptor = pudu_host_socket_find(token), code = 0;"
      , "  size_t sent = 0;"
      , "  if (descriptor < 0) { pudu_host_fail(\"the endpoint is closed\"); return 0; }"
      , "  if (budget == 0) code = -1;"
      , "  else {"
      , "    int64_t started = pudu_host_socket_clock();"
      , "    pudu_host_leave();"
      , "    while (sent < bytes.length) {"
      , "      ssize_t wrote = send(descriptor, bytes.bytes + sent, bytes.length - sent, PUDU_HOST_SEND_FLAGS);"
      , "      if (wrote >= 0) { sent += (size_t)wrote; continue; }"
      , "      if (errno == EINTR) continue;"
      , "      if (errno == EAGAIN || errno == EWOULDBLOCK) {"
      , "        if (!pudu_host_socket_ready(descriptor, POLLOUT, budget, started)) { code = -1; break; }"
      , "        continue;"
      , "      }"
      , "      code = errno;"
      , "      break;"
      , "    }"
      , "    pudu_host_enter();"
      , "  }"
      , "  if (code < 0) { pudu_host_socket_timed_out(token); return 0; }"
      , "  if (code != 0) { pudu_host_fail_io(none, \"Network.Socket.sendBuf\", code); return 0; }"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_socket_send", ["host_socket_sending"],
      [ "static int pudu_host_socket_send(pudu_int token, pudu_box *chunk) { return pudu_host_socket_sending(token, chunk, -1); }"
      ])
  , ("host_socket_send_within", ["host_socket_sending"],
      [ "static int pudu_host_socket_send_within(pudu_int token, pudu_box *chunk, pudu_int within) {"
      , "  int64_t budget = pudu_kernel_signed(within.bits);"
      , "  return pudu_host_socket_sending(token, chunk, budget < 0 ? -1 : budget);"
      , "}"
      ])
  , ("host_socket_receiving", ["host_sockets", "kernel_fresh", "bytes_wrap"],
      [ "/* Up to count bytes; state 2 when the other end will send no more. */"
      , "PUDU_OPTIONAL static inline pudu_box *pudu_host_socket_receiving(pudu_int token, pudu_int count, int64_t budget) {"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL}, chunk;"
      , "  int64_t wanted = pudu_kernel_signed(count.bits);"
      , "  unsigned char *bytes;"
      , "  ssize_t got = 0;"
      , "  int descriptor, code = 0;"
      , "  if (wanted <= 0) { pudu_host_done(0); return pudu_bytes_wrap(pudu_kernel_fresh(0, &bytes)); }"
      , "  descriptor = pudu_host_socket_find(token);"
      , "  if (descriptor < 0) { pudu_host_fail(\"the endpoint is closed\"); return NULL; }"
      , "  chunk = pudu_kernel_fresh((size_t)wanted, &bytes);"
      , "  if (budget == 0) code = -1;"
      , "  else {"
      , "    int64_t started = pudu_host_socket_clock();"
      , "    pudu_host_leave();"
      , "    for (;;) {"
      , "      got = recv(descriptor, bytes, (size_t)wanted, 0);"
      , "      if (got >= 0) break;"
      , "      if (errno == EINTR) continue;"
      , "      if (errno == EAGAIN || errno == EWOULDBLOCK) {"
      , "        if (!pudu_host_socket_ready(descriptor, POLLIN, budget, started)) { code = -1; break; }"
      , "        continue;"
      , "      }"
      , "      code = errno;"
      , "      break;"
      , "    }"
      , "    pudu_host_enter();"
      , "  }"
      , "  if (code != 0 || got == 0) pudu_text_release(chunk);"
      , "  if (code < 0) { pudu_host_socket_timed_out(token); return NULL; }"
      , "  if (code != 0) { pudu_host_fail_io(none, \"Network.Socket.recvBuf\", code); return NULL; }"
      , "  if (got == 0) { pudu_host_done(2); return NULL; }"
      , "  chunk.length = (size_t)got;"
      , "  pudu_host_done(0);"
      , "  return pudu_bytes_wrap(chunk);"
      , "}"
      ])
  , ("host_socket_receive", ["host_socket_receiving"],
      [ "static pudu_box *pudu_host_socket_receive(pudu_int token, pudu_int count) { return pudu_host_socket_receiving(token, count, -1); }"
      ])
  , ("host_socket_receive_within", ["host_socket_receiving"],
      [ "static pudu_box *pudu_host_socket_receive_within(pudu_int token, pudu_int count, pudu_int within) {"
      , "  int64_t budget = pudu_kernel_signed(within.bits);"
      , "  return pudu_host_socket_receiving(token, count, budget < 0 ? -1 : budget);"
      , "}"
      ])
  , ("host_socket_finish", ["host_sockets"],
      [ "/* Nothing more will be sent; what arrives is still read. */"
      , "static int pudu_host_socket_finish(pudu_int token) {"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "  int descriptor = pudu_host_socket_find(token);"
      , "  if (descriptor < 0) { pudu_host_fail(\"the endpoint is closed\"); return 0; }"
      , "  if (shutdown(descriptor, SHUT_WR) != 0) { pudu_host_fail_io(none, \"Network.Socket.shutdown\", errno); return 0; }"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_socket_close", ["host_sockets"],
      [ "/* Closing an endpoint that is not open is done already. */"
      , "static int pudu_host_socket_close(pudu_int token) {"
      , "  int descriptor = pudu_host_socket_take(token);"
      , "  if (descriptor >= 0) (void)close(descriptor);"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_socket_named", ["host_sockets"],
      [ "/* An address as text: `a.b.c.d:port`, or `[address]:port` for the wider family. */"
      , "PUDU_OPTIONAL static inline int pudu_host_socket_named(const struct sockaddr_storage *held, char *words, size_t room, int *port) {"
      , "  char address[INET6_ADDRSTRLEN];"
      , "  if (held->ss_family == AF_INET) {"
      , "    const struct sockaddr_in *narrow = (const struct sockaddr_in *)(const void *)held;"
      , "    if (inet_ntop(AF_INET, &narrow->sin_addr, address, sizeof address) == NULL) return 0;"
      , "    *port = (int)ntohs(narrow->sin_port);"
      , "    (void)snprintf(words, room, \"%s:%d\", address, *port);"
      , "    return 1;"
      , "  }"
      , "  if (held->ss_family == AF_INET6) {"
      , "    const struct sockaddr_in6 *wide = (const struct sockaddr_in6 *)(const void *)held;"
      , "    if (inet_ntop(AF_INET6, &wide->sin6_addr, address, sizeof address) == NULL) return 0;"
      , "    *port = (int)ntohs(wide->sin6_port);"
      , "    (void)snprintf(words, room, \"[%s]:%d\", address, *port);"
      , "    return 1;"
      , "  }"
      , "  return 0;"
      , "}"
      ])
  , ("host_socket_peer", ["host_socket_named", "text_copy"],
      [ "/* Who is at the other end. */"
      , "static pudu_text pudu_host_socket_peer(pudu_int token) {"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "  struct sockaddr_storage held;"
      , "  socklen_t size = sizeof held;"
      , "  char words[INET6_ADDRSTRLEN + 16];"
      , "  int descriptor = pudu_host_socket_find(token), port = 0;"
      , "  if (descriptor < 0) { pudu_host_fail(\"the endpoint is closed\"); return none; }"
      , "  memset(&held, 0, sizeof held);"
      , "  if (getpeername(descriptor, (struct sockaddr *)&held, &size) != 0) { pudu_host_fail_io(none, \"Network.Socket.getPeerName\", errno); return none; }"
      , "  if (!pudu_host_socket_named(&held, words, sizeof words, &port)) words[0] = 0;"
      , "  pudu_host_done(0);"
      , "  return pudu_text_copy(words, strlen(words));"
      , "}"
      ])
  , ("host_socket_port", ["host_socket_named"],
      [ "/* Which port an endpoint is on, as the system chose or was told. */"
      , "static pudu_int pudu_host_socket_port(pudu_int token) {"
